pub fn verify_qap_certificate(cert: &QapCertificate) -> Result<(), ProgramError> {
    if !cert.verify() {
        msg!("QAP certificate verification failed for {}", cert.source_name);
        return Err(ProgramError::InvalidAccountData);
    }
    msg!("QAP verified: {} risk {} ({}) constraints {} wires {} algo {}",
        cert.source_name, cert.risk_score, cert.risk_level(), cert.r1cs_constraints, cert.r1cs_wires, "f4f5");
